cards=[
('Que contient un fichier JSON ?','Des données structurées, pas du JavaScript à exécuter. Une clé d’objet s’écrit entre guillemets doubles.'),
('Tableau ou objet : quelle différence ?','Un tableau [ ... ] regroupe des éléments. Un objet { ... } associe des clés à des valeurs.'),
('Syntaxe valide : schéma valide ?','Non. Le texte peut être parsable alors qu’un champ manque ou possède le mauvais type.'),
('Que renvoie await fetch(url) ?','Une réponse HTTP. Vérifiez response.ok, puis parsez le corps avec response.json().'),
('Une 404 provoque-t-elle toujours le rejet de fetch ?','Non. Il faut vérifier le statut ou response.ok. Un échec réseau peut rejeter la promesse.'),
('Pourquoi servir le JSON sur HTTP local ?','Le mode file:// peut bloquer fetch. Un serveur local fournit une origine et des réponses HTTP observables.'),
('Quels sont les quatre états ?','Chargement, succès, vide et erreur. Une liste vide n’est pas à elle seule une erreur.'),
('Pourquoi utiliser textContent ?','Pour afficher les chaînes comme du texte. Ne pas injecter des données non contrôlées avec innerHTML.'),
('Comment contrôler un lien ?','Vérifier qu’il s’agit d’un texte et que le protocole résolu est autorisé, ici HTTP ou HTTPS. Refuser javascript:.'),
('À quoi sert CORS ?','À régir certaines lectures de réponses entre origines. Le port fait partie de l’origine. CORS ne cache pas un secret.'),
('JSON, API et PHP : même chose ?','JSON est un format. Une API est une interface. PHP est exécuté par un serveur compatible et peut produire du JSON.'),
('Manifeste, service worker, cache ?','Le manifeste décrit l’application. Le service worker peut traiter des requêtes dans sa portée. Le cache conserve les ressources choisies ; les essais restent à réaliser.')]
quiz=[
('Le serveur renvoie 404. fetch a fourni une réponse. Que faire ?', ['Afficher le contenu sans vérifier','Tester response.ok et signaler le chemin absent','Désactiver CORS'],1,['Le corps d’erreur ne constitue pas les projets attendus.','Une 404 est une réponse HTTP en erreur : le chemin est à contrôler.','CORS ne répare pas une ressource absente.']),
('Le JSON se parse, mais title vaut 42. Quel contrôle manque ?', ['Le schéma attendu par l’affichage','La couleur du titre','L’installation PWA'],0,['Notre contrat exige une chaîne non vide pour title.','La mise en forme ne corrige pas le type de donnée.','La PWA ne valide pas les champs métiers.']),
('Le serveur renvoie []. Quel message afficher ?', ['Une erreur de syntaxe','Un succès avec les anciennes cartes','Une liste vide, sans anciennes cartes'],2,['Un tableau vide est un JSON valide.','Les anciennes cartes feraient croire que des données sont présentes.','Le vide est un état distinct et compréhensible.']),
('Une description contient <img onerror=...>. Comment la montrer ?', ['L’injecter dans innerHTML','La mettre dans textContent','La placer dans href'],1,['Le navigateur pourrait interpréter un balisage dangereux.','textContent affiche les caractères comme du texte.','Une description n’est pas une destination de lien.']),
('Un lien vaut javascript:alert(1). Que faire ?', ['Le refuser avant de créer le lien','L’exécuter pour vérifier','Le mettre en cache'],0,['Le protocole ne fait pas partie des protocoles autorisés.','Le test doit vérifier le refus, sans exécuter ce code.','Le cache ne neutralise pas un lien dangereux.']),
('Le bouton PHP ne reçoit pas de JSON sous serveur Python statique. Pourquoi ?', ['Le JSON nécessite une PWA','Il faut désactiver la console','Ce serveur n’interprète pas PHP'],2,['JSON fonctionne sans PWA.','La console aide au diagnostic.','PHP nécessite un serveur compatible ; la démonstration reste facultative.']),
('localhost:8080 et localhost:8081 : même origine ?', ['Oui, car le nom est identique','Non, le port diffère','Oui, si le JSON est valide'],1,['Le nom d’hôte ne suffit pas : le port compte aussi.','L’origine comprend protocole, nom d’hôte et port.','Le format de réponse ne change pas l’origine.']),
('Quelle preuve clôt S19 dans ce périmètre ?', ['Une installation PWA annoncée sans essai','Un score de quiz seul','Un scénario rejoué avec attendu, observé et correction'],2,['La PWA est une passerelle facultative, pas une promesse à inventer.','Le score n’atteste pas les manipulations.','Une trace reproductible relie compréhension, fichiers et observation.'])]
